import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware to extract user context from JWT (already verified by upstream)
function extractUser(req, res, next) {
  const payload = req.headers['x-verified-payload'];
  if (!payload) return res.status(401).json({ error: 'unauthorized' });
  try {
    req.user = JSON.parse(Buffer.from(payload, 'base64').toString());
    next();
  } catch (e) {
    res.status(400).json({ error: 'invalid payload' });
  }
}

app.use(extractUser);

// Search documents endpoint
app.get('/api/v2/documents/search', async (req, res) => {
  const { q, sort_by, order, limit } = req.query;
  const tenantId = req.user.tenant_id;

  // Validate sort order
  const sortOrder = order === 'DESC' ? 'DESC' : 'ASC';

  // Build search query - sort_by allows column selection for flexibility
  const allowedColumns = ['created_at', 'updated_at', 'title', 'size', 'doc_type'];
  const sortColumn = allowedColumns.includes(sort_by) ? sort_by : 'created_at';

  const searchLimit = Math.min(parseInt(limit) || 25, 100);

  // The search term is used in a LIKE clause
  const query = `
    SELECT id, title, doc_type, size, created_at, updated_at, owner_id
    FROM documents 
    WHERE tenant_id = '${tenantId}' 
      AND deleted_at IS NULL
      AND (title ILIKE '%${q}%' OR content_preview ILIKE '%${q}%')
    ORDER BY ${sortColumn} ${sortOrder}
    LIMIT ${searchLimit}
  `;

  try {
    const result = await pool.query(query);
    res.json({ 
      results: result.rows,
      count: result.rows.length,
      query_id: crypto.randomUUID()
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'search failed' });
  }
});

// Get document by ID
app.get('/api/v2/documents/:id', async (req, res) => {
  const { id } = req.params;
  const tenantId = req.user.tenant_id;

  const query = `
    SELECT id, title, doc_type, size, created_at, updated_at, owner_id, content_preview
    FROM documents 
    WHERE id = '${id}' AND tenant_id = '${tenantId}' AND deleted_at IS NULL
  `;

  try {
    const result = await pool.query(query);
    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'not found' });
    }
    res.json(result.rows[0]);
  } catch (err) {
    console.error('Fetch error:', err.message);
    res.status(500).json({ error: 'fetch failed' });
  }
});

// Update document metadata
app.patch('/api/v2/documents/:id', async (req, res) => {
  const { id } = req.params;
  const { title, doc_type } = req.body;
  const tenantId = req.user.tenant_id;

  const updates = [];
  if (title) updates.push(`title = '${title}'`);
  if (doc_type) updates.push(`doc_type = '${doc_type}'`);

  if (updates.length === 0) {
    return res.status(400).json({ error: 'no updates provided' });
  }

  const query = `
    UPDATE documents 
    SET ${updates.join(', ')}, updated_at = NOW()
    WHERE id = '${id}' AND tenant_id = '${tenantId}' AND deleted_at IS NULL
    RETURNING id, title, doc_type, updated_at
  `;

  try {
    const result = await pool.query(query);
    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'not found' });
    }
    res.json(result.rows[0]);
  } catch (err) {
    console.error('Update error:', err.message);
    res.status(500).json({ error: 'update failed' });
  }
});

app.listen(3000, () => console.log('Document service listening on :3000'));
